import json, sys, datetime

def get_text(msg):
    content = msg.get("content")
    if isinstance(content, str):
        return content
    out = []
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                continue
            t = block.get("type")
            if t == "text":
                out.append(block.get("text", ""))
            elif t == "tool_use":
                out.append(f"[TOOL_USE {block.get('name')} input={json.dumps(block.get('input',{}))[:300]}]")
            elif t == "tool_result":
                c = block.get("content")
                if isinstance(c, list):
                    c = " ".join(b.get("text","") for b in c if isinstance(b, dict))
                out.append(f"[TOOL_RESULT {str(c)[:300]}]")
    return "\n".join(out)

def main(path):
    with open(path) as f:
        lines = [l for l in f if l.strip()]
    entries = []
    for l in lines:
        try:
            entries.append(json.loads(l))
        except Exception:
            continue

    print(f"=== {path} — {len(entries)} entries ===")
    ts_list = []
    for e in entries:
        ts = e.get("timestamp")
        if ts:
            ts_list.append(ts)
    if ts_list:
        print(f"first ts: {ts_list[0]}  last ts: {ts_list[-1]}")

    prev_ts = None
    for i, e in enumerate(entries):
        etype = e.get("type")
        ts = e.get("timestamp")
        gap = ""
        if ts and prev_ts:
            try:
                t0 = datetime.datetime.fromisoformat(prev_ts.replace("Z","+00:00"))
                t1 = datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
                delta = (t1-t0).total_seconds()
                if delta > 60:
                    gap = f"  <<GAP {delta:.0f}s>>"
            except Exception:
                pass
        if ts:
            prev_ts = ts

        if e.get("attachment"):
            att = e["attachment"]
            print(f"[{i}] ATTACHMENT {att.get('type')} hook={att.get('hookName')}{gap}")
            continue

        msg = e.get("message")
        if not msg:
            continue
        role = msg.get("role")
        text = get_text(msg)
        text = text.strip()
        if not text:
            continue
        prefix = f"[{i}] {role} sidechain={e.get('isSidechain')}{gap}"
        # truncate long text
        snippet = text[:500]
        print(f"{prefix}\n{snippet}\n")

if __name__ == "__main__":
    main(sys.argv[1])

